import sys, numpy as np
from PIL import Image
sys.path.insert(0,'/opt/tools'); from rcb_client import Robot
r=Robot(); o=r.get_obs(depth=True,video='none');
for c,a in o.last.items(): Image.fromarray(a).save('/app/output/current_'+c+'.png')
for c,d in o.last_depth.items(): np.save('/app/output/current_depth_'+c+'.npy',d)
p=o.meta['proprio']['now']; print('tcp',p[8:15], 'opening',p[24], 'left',o.meta['time_left_s'])
D=o.last_depth['egocentric_mirrored_camera'];K=np.array([[989.549,0,432],[0,989.549,240],[0,0,1]])
E=np.array(o.meta['cameras']['egocentric_mirrored_camera']['extrinsic_cv']); Ei=np.linalg.inv(np.vstack([E,[0,0,0,1]]))
for u,v in [(230,65),(230,75),(230,85),(230,95),(230,105),(230,115),(230,125),(230,135),(230,145)]:
 vals=D[v-1:v+2,u-1:u+2].ravel();vals=vals[vals>0];z=np.median(vals) if len(vals) else 0
 if z:
  pc=np.linalg.inv(K)@np.array([u,v,1.])*z;w=Ei@np.r_[pc,1]; print((u,v),round(z,3),np.round(w[:3],3))
